        SELECT * FROM (

        SELECT  FROM ifj_event
        WHERE event_code = #{eventCode} AND arrived_at >= #{acceptAfter}
          AND (#{businessKey} IS NULL OR business_key = #{businessKey})
          AND (#{correlationKey} IS NULL OR correlation_key = #{correlationKey})
        ORDER BY arrived_at ASC, id ASC
        ) WHERE ROWNUM <= #{limit}
